329	        return;
330	      }
331	      if (name === "from" || name === "to") {
332	        const date = parseUtcTimestamp(raw);
333	        if (date === null) {
334	          badRequest(response, `${name} must be a UTC timestamp formatted as YYYY-MM-DDTHH:mm:ss.SSSZ`);
335	          return;
336	        }
337	        if (name === "from") {
338	          fromIso = raw;
339	        } else {
340	          toIso = raw;
341	        }
342	      } else if (name === "limit") {
343	        if (!DECIMAL_INTEGER_PATTERN.test(raw) || raw.length > 9) {
344	          badRequest(response, "limit must be a decimal integer between 1 and 100");
345	          return;
346	        }
