349	          badRequest(response, "limit must be a decimal integer between 1 and 100");
350	          return;
351	        }
352	      } else {
353	        cursorToken = raw;
354	      }
355	    }
356	
357	    if (fromIso !== null && toIso !== null && Date.parse(toIso) < Date.parse(fromIso)) {
358	      badRequest(response, "to must not be earlier than from");
359	      return;
360	    }
361	
362	    let cursor = null;
363	    if (cursorToken !== undefined) {
364	      cursor = decodeCursor(cursorToken);
365	      if (cursor === null) {
366	        badRequest(response, "cursor is invalid");
367	        return;
368	      }
369	      if (
370	        cursor.sid !== id
371	        || cursor.from !== fromIso
372	        || cursor.to !== toIso
373	        || cursor.limit !== limit
374	      ) {
375	        badRequest(response, "cursor does not match this query");
376	        return;
377	      }
378	      if (cursor.rev !== scenario.revision) {
379	        badRequest(response, "cursor is no longer valid because the scenario was modified");
380	        return;
381	      }
382	    }
383	
384	    const fromTime = fromIso === null ? null : Date.parse(fromIso);
385	    const toTime = toIso === null ? null : Date.parse(toIso);
386	    const afterSequence = cursor === null ? 0 : cursor.seq;
387	
388	    const page = [];
389	    let nextSequence = 0;
390	    for (const event of scenario.events) {
391	      if (event.sequence <= afterSequence) {
392	        continue;
393	      }
394	      const occurredAt = Date.parse(event.occurredAt);
395	      if (fromTime !== null && occurredAt < fromTime) {
396	        continue;
397	      }
398	      if (toTime !== null && occurredAt > toTime) {
399	        continue;
400	      }
401	      if (page.length === limit) {
402	        nextSequence = page[page.length - 1].sequence;
403	        break;
404	      }
405	      page.push(event);
406	    }
407	
408	    let nextCursor = null;
409	    if (nextSequence > 0) {
410	      nextCursor = encodeCursor({
411	        v: 1,
412	        sid: id,
413	        from: fromIso,
414	        to: toIso,
415	        limit,
416	        seq: nextSequence,
417	        rev: scenario.revision
418	      });
419	    }
420	
421	    sendJson(response, 200, {
422	      revision: scenario.revision,
423	      events: page,
424	      nextCursor
425	    });
426	  }
427	
428	  async function handleRequest(request, response) {
429	    const url = new URL(request.url ?? "/", "http://branchline.local");
430	    const segments = url.pathname.split("/");
431	
432	    try {
433	      if (request.method === "GET" && url.pathname === "/health") {
434	        sendJson(response, 200, {
435	          status: "ok",
436	          service: "branchline-core",
437	          version: "0.1.0"
438	        });
439	        return;
440	      }
441	
442	      if (segments.length === 2 && segments[1] === "scenarios") {
443	        if (request.method === "POST") {
444	          await createScenario(request, response);
445	          return;
446	        }
447	        if (request.method === "GET") {
448	          listScenarios(response);
449	          return;
450	        }
451	      } else if (segments.length === 3 && segments[1] === "scenarios") {
452	        const id = decodeURIComponent(segments[2]);
453	        if (request.method === "GET") {
454	          getScenario(response, id);
455	          return;
456	        }
457	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "branches") {
458	        const id = decodeURIComponent(segments[2]);
459	        if (request.method === "POST") {
460	          await createBranch(request, response, id);
461	          return;
462	        }
463	      } else if (segments.length === 4 && segments[1] === "scenarios" && segments[3] === "events") {
464	        const id = decodeURIComponent(segments[2]);
465	        if (request.method === "POST") {
466	          await appendEvent(request, response, id);
467	          return;
468	        }
469	        if (request.method === "GET") {
470	          listEvents(response, id, url);
471	          return;
472	        }
473	      }
474	
475	      notFound(response, "Route not found");
476	    } catch (error) {
477	      sendJson(response, 500, { error: "internal_error", message: "Internal server error" });
478	    }
479	  }
480	
481	  return { handleRequest };
482	}
483	
484	const defaultApp = createApp();
485	
